using System.ComponentModel.Composition;
using Microsoft.Dynamics.ApplicationPlatform.FeatureExposure;

/// <summary>
/// The <c>SysMonitoringAndTelemetryFeature</c> class represents the monitoring and telemetry feature in feature management.
/// </summary>
[Export(identifierStr(Microsoft.Dynamics.ApplicationPlatform.FeatureExposure.IFeatureMetadata))]
internal final class SysMonitoringAndTelemetryFeature implements IFeatureMetadata, IFeatureLifecycle
{
    private static SysMonitoringAndTelemetryFeature instance;

}

Method.Source:
private static void TypeNew()
{
    instance = new SysMonitoringAndTelemetryFeature();
}

/// <summary>
/// Obtains the singleton object instance.
/// </summary>
